"""T3 textbook-evidence tool (smoke) on Kaggle 2xT4: one model per GPU. Generated by launch_textbook_tool.py."""
import base64, json, os, subprocess, sys, threading, time, zlib
from pathlib import Path

PAYLOAD_B64 = ""


def main():
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", *['transformers==5.17.0', 'accelerate==1.15.0', 'bitsandbytes==0.50.2']], check=True)
    p = json.loads(zlib.decompress(base64.b64decode(PAYLOAD_B64)))
    project = Path("/kaggle/working/t3/PROJECT")
    for rel, text in p["files"].items():
        path = project / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    import torch
    assert torch.cuda.device_count() == 2, "Two GPUs required; refusing a one-GPU run"
    print("DUAL_GPU_CONFIRMED", [torch.cuda.get_device_name(i) for i in range(2)], flush=True)
    from huggingface_hub import snapshot_download
    cache = Path("/tmp/t3_model_cache")
    for name, spec in p["models"].items():
        snapshot_download(repo_id=spec["repo"], revision=spec["revision"], cache_dir=cache,
                          allow_patterns=["*.json", "*.safetensors", "*.model", "tokenizer*", "*.py", "*.txt"])
        refs = cache / ("models--" + spec["repo"].replace("/", "--")) / "refs"
        refs.mkdir(parents=True, exist_ok=True)
        (refs / "main").write_text(spec["revision"], encoding="utf-8")
        print("MODEL_READY", name, spec["revision"], flush=True)
    out = project / p["out"]
    procs, threads = [], []

    def relay(proc, gpu, name):
        with (out / f"{name}_worker.log").open("a", encoding="utf-8") as log:
            for line in proc.stdout:
                log.write(line); log.flush()
                print(f"[GPU{gpu}/{name}] {line.rstrip()}", flush=True)

    for gpu, name in enumerate(p["models"]):
        cmd = [sys.executable, "-m", "analysis.textbook_tool", "--worker", "--mode", p["mode"], "--gpu", str(gpu),
               "--model", name, "--model-root", str(cache), "--host", "Kaggle 2xT4"]
        proc = subprocess.Popen(cmd, cwd=str(project / "codebase/src"), stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                text=True, encoding="utf-8", errors="replace", bufsize=1,
                                env=dict(os.environ, CUDA_VISIBLE_DEVICES=str(gpu), PYTHONUNBUFFERED="1",
                                         TOKENIZERS_PARALLELISM="false", PYTHONPATH=str(project / "codebase/src")))
        procs.append(proc)
        th = threading.Thread(target=relay, args=(proc, gpu, name), daemon=True); th.start(); threads.append(th)
        print("MODEL_STARTED", name, "GPU", gpu, flush=True)
    codes = [proc.wait() for proc in procs]
    for th in threads:
        th.join(timeout=10)
    result = dict(codes=dict(zip(p["models"], codes)),
                  completed={n: json.loads((out / n / "completed.json").read_text()) if (out / n / "completed.json").exists() else None
                             for n in p["models"]})
    (out / "kaggle_completed.json").write_text(json.dumps(result, indent=2), encoding="utf-8")
    print("T3_RESULT", json.dumps(result), flush=True)
    if any(codes):
        raise SystemExit(f"Worker failed: {codes}")
    print("T3_KAGGLE_COMPLETE", flush=True)


if __name__ == "__main__":
    main()
